import"./chunk-VC46IEJQ.js";var e={id:"storms-end",intro:{en:"A single colossal drum tower on a cliff above Shipbreaker Bay, ringed by a curtain wall of enormous thickness. Legend says Durran, the first Storm King, raised it to defy the gods' storms; since the Conquest it has been the seat of House Baratheon. This is a reconstruction of what the books describe in outline.",zh:"\u98CE\u606F\u5821\u662F\u7834\u8239\u6E7E\u6D77\u5D16\u4E0A\u7684\u4E00\u5EA7\u5DE8\u578B\u9F13\u5854\uFF0C\u56DB\u5468\u73AF\u7ED5\u539A\u5F97\u60CA\u4EBA\u7684\u5E55\u5899\u3002\u76F8\u4F20\u9996\u4F4D\u98CE\u66B4\u738B\u675C\u5170\u7B51\u6B64\u5821\u4EE5\u6297\u8861\u8BF8\u795E\u7684\u98CE\u66B4\uFF1B\u5F81\u670D\u6218\u4E89\u4EE5\u6765\uFF0C\u5B83\u4E00\u76F4\u662F\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u672C\u573A\u666F\u4F9D\u636E\u4E66\u4E2D\u7684\u8F6E\u5ED3\u5F0F\u63CF\u5199\u91CD\u6784\u3002"},notes:{en:"From the books: one immense drum tower, no other towers; a round curtain wall about 100 ft high and at least 40 ft thick, nearly 80 ft on the seaward side; a cliff above Shipbreaker Bay; the Kingswood to the north. Invented: all plan details, the gatehouse, the bailey buildings, the village, the sea stacks and the surrounding landscape.",zh:"\u4E66\u4E2D\u786E\u7ACB\uFF1A\u4E00\u5EA7\u5DE8\u578B\u9F13\u5854\uFF0C\u6B64\u5916\u522B\u65E0\u5854\u697C\uFF1B\u73AF\u5F62\u5E55\u5899\u9AD8\u7EA6\u767E\u5C3A\uFF0C\u6700\u8584\u5904\u539A\u7EA6\u56DB\u5341\u5C3A\uFF0C\u4E34\u6D77\u4E00\u4FA7\u8FD1\u516B\u5341\u5C3A\uFF1B\u57CE\u5821\u7ACB\u4E8E\u7834\u8239\u6E7E\u4E4B\u4E0A\u7684\u60AC\u5D16\uFF1B\u5317\u9762\u662F\u5FA1\u6797\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5168\u90E8\u5E73\u9762\u7EC6\u8282\u3001\u57CE\u95E8\u697C\u3001\u9662\u5185\u5EFA\u7B51\u3001\u6751\u843D\u3001\u6D77\u8680\u67F1\u4E0E\u5468\u8FB9\u5730\u8C8C\u3002"},tour:["shipbreaker-bay","seaward-cliff","seaward-wall","great-drum-tower","rookery","bailey","landward-wall","gatehouse","fishing-hamlet","kingswood-edge"],sources:[{ref:"acok",checked:"memory",note:{en:"Catelyn's visit to Renly's camp before Storm's End describes the wall and the great tower; Davos recalls the siege of Robert's Rebellion. Recalled, not re-read.",zh:"\u51EF\u7279\u7433\u9020\u8BBF\u98CE\u606F\u5821\u57CE\u5916\u84DD\u793C\u8425\u5730\u7684\u7AE0\u8282\u63CF\u5199\u4E86\u57CE\u5899\u4E0E\u5DE8\u5854\uFF1B\u6234\u4F5B\u65AF\u5219\u56DE\u5FC6\u4E86\u52B3\u52C3\u8D77\u4E49\u65F6\u7684\u56F4\u57CE\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki confirmed the wall figures (100 ft high, 40 ft thick at its thinnest, nearly 80 ft seaward), the single windowless-to-the-sea drum tower containing hall, barracks and lord's chambers, and the maester's rookery at its top. Pages not fetched.",zh:"\u7EF4\u57FA\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u57CE\u5899\u6570\u636E\uFF08\u9AD8\u767E\u5C3A\uFF0C\u6700\u8584\u5904\u539A\u56DB\u5341\u5C3A\uFF0C\u4E34\u6D77\u4E00\u4FA7\u8FD1\u516B\u5341\u5C3A\uFF09\u3001\u552F\u4E00\u4E00\u5EA7\u9762\u6D77\u65E0\u7A97\u3001\u5185\u542B\u5927\u5385\u5175\u8425\u4E0E\u9886\u4E3B\u5C45\u6240\u7684\u9F13\u5854\uFF0C\u4EE5\u53CA\u5854\u9876\u7684\u5B66\u58EB\u9E26\u5DE2\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}},{ref:"twoiaf",checked:"memory",note:{en:"The legend of Durran Godsgrief and the Storm Kings. Recalled.",zh:"\u98CE\u66B4\u738B\u675C\u5170\u53CA\u5176\u540E\u5386\u4EE3\u98CE\u66B4\u738B\u7684\u4F20\u8BF4\u3002\u51ED\u8BB0\u5FC6\u3002"}},{ref:"maps",checked:"not-accessed",note:{en:"No official plan of the castle was available.",zh:"\u672A\u80FD\u67E5\u9605\u5B98\u65B9\u57CE\u5821\u5E73\u9762\u56FE\u3002"}}],landmarks:{"great-drum-tower":{name:{en:"Great Drum Tower",zh:"\u5DE8\u9F13\u5854"},desc:{en:"The immense round tower that is the whole keep: windowless on the sea side, crowned with heavy battlements.",zh:"\u4E00\u5EA7\u517C\u4F5C\u4E3B\u5821\u7684\u5DE8\u5927\u5706\u5854\uFF1A\u9762\u6D77\u4E00\u4FA7\u4E0D\u5F00\u7A97\uFF0C\u5854\u9876\u662F\u539A\u91CD\u7684\u579B\u53E3\u3002"},tour:{en:"One colossal drum of stone holds hall, barracks, armoury and lord's chambers alike.",zh:"\u4E00\u5EA7\u5DE8\u5927\u7684\u77F3\u9F13\uFF0C\u5927\u5385\u3001\u5175\u8425\u3001\u6B66\u5E93\u4E0E\u9886\u4E3B\u5C45\u6240\u5C3D\u5728\u5176\u4E2D\u3002"},spoiler:{en:"In A Dance with Dragons the castle changes hands in a surprise attack.",zh:"\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u6B64\u5821\u906D\u7A81\u88AD\u800C\u6613\u4E3B\u3002"},source:{confidence:"high",refs:["acok","awoiaf"],book:{en:"Storm's End has a single great drum tower, windowless toward the sea, large enough to hold granary, barracks, feast hall and the lord's rooms.",zh:"\u98CE\u606F\u5821\u53EA\u6709\u4E00\u5EA7\u5DE8\u5927\u7684\u9F13\u5854\uFF0C\u9762\u6D77\u4E00\u4FA7\u65E0\u7A97\uFF0C\u5927\u5230\u8DB3\u4EE5\u5BB9\u7EB3\u7CAE\u4ED3\u3001\u5175\u8425\u3001\u5BB4\u4F1A\u5385\u4E0E\u9886\u4E3B\u5C45\u5BA4\u3002"},unknown:{en:"Exact diameter, height and interior layout.",zh:"\u786E\u5207\u76F4\u5F84\u3001\u9AD8\u5EA6\u4E0E\u5185\u90E8\u5E03\u5C40\u3002"},interpretation:{en:"A tapered drum with battlements and an inner turret, with arrow-slits only on the landward side.",zh:"\u7565\u6709\u6536\u5206\u7684\u9F13\u5F62\u5854\uFF0C\u8BBE\u579B\u53E3\u4E0E\u5185\u4FA7\u5C0F\u5854\uFF0C\u4EC5\u9646\u4FA7\u5F00\u7BAD\u5B54\u3002"}}},"seaward-wall":{name:{en:"Seaward Wall",zh:"\u4E34\u6D77\u57CE\u5899"},desc:{en:"The cliff-edge stretch of the curtain wall, many times thicker than an ordinary castle wall.",zh:"\u5E55\u5899\u4E34\u5D16\u7684\u4E00\u6BB5\uFF0C\u539A\u5EA6\u662F\u5BFB\u5E38\u57CE\u5899\u7684\u6570\u500D\u3002"},tour:{en:"Facing the open sea, the wall is at its thickest: nearly eighty feet.",zh:"\u9762\u671D\u5927\u6D77\u7684\u4E00\u6BB5\u6700\u539A\uFF0C\u8FD1\u516B\u5341\u5C3A\u3002"},source:{confidence:"high",refs:["acok","awoiaf"],book:{en:"The curtain wall is nearly eighty feet thick on the seaward side.",zh:"\u5E55\u5899\u4E34\u6D77\u4E00\u4FA7\u539A\u8FD1\u516B\u5341\u5C3A\u3002"},unknown:{en:"Whether every source gives the same figure.",zh:"\u5404\u6765\u6E90\u6570\u5B57\u662F\u5426\u4E00\u81F4\u3002"},interpretation:{en:"A wide arc of stone with merlons on both faces.",zh:"\u4E00\u9053\u5BBD\u9614\u7684\u77F3\u5899\u5F27\uFF0C\u5185\u5916\u4E24\u4FA7\u90FD\u8BBE\u579B\u53E3\u3002"}}},"landward-wall":{name:{en:"Landward Wall",zh:"\u9646\u4FA7\u57CE\u5899"},desc:{en:"The thinner landward curtain, still far heavier than most walls, enclosing the bailey.",zh:"\u9646\u4FA7\u8F83\u8584\u7684\u5E55\u5899\uFF0C\u4ECD\u8FDC\u6BD4\u5BFB\u5E38\u57CE\u5899\u539A\u91CD\uFF0C\u5708\u51FA\u57CE\u5185\u9662\u843D\u3002"},tour:{en:'Landward the wall is "only" forty feet thick and a hundred high.',zh:"\u9646\u4FA7\u57CE\u5899\u201C\u4EC5\u201D\u539A\u56DB\u5341\u5C3A\uFF0C\u9AD8\u8FBE\u767E\u5C3A\u3002"},source:{confidence:"high",refs:["acok","awoiaf"],book:{en:"The round curtain wall is about 100 ft high and 40 ft thick at its thinnest, built of pale grey stone around a core of sand and rubble.",zh:"\u73AF\u5F62\u5E55\u5899\u9AD8\u7EA6\u767E\u5C3A\uFF0C\u6700\u8584\u5904\u539A\u56DB\u5341\u5C3A\uFF0C\u4EE5\u6D45\u7070\u77F3\u6599\u780C\u6210\uFF0C\u5185\u586B\u6C99\u571F\u4E0E\u788E\u77F3\u3002"},unknown:{en:"The exact circuit and gate arrangement.",zh:"\u57CE\u5899\u786E\u5207\u8D70\u5411\u4E0E\u57CE\u95E8\u5E03\u7F6E\u3002"},interpretation:{en:"A smooth arc with no towers, keeping the single great tower unrivalled.",zh:"\u4E0D\u8BBE\u5854\u697C\u7684\u5E73\u6ED1\u5F27\u5899\uFF0C\u8BA9\u552F\u4E00\u7684\u5DE8\u5854\u65E0\u53EF\u5339\u654C\u3002"}}},gatehouse:{name:{en:"Gatehouse",zh:"\u57CE\u95E8\u697C"},desc:{en:"A squat gatehouse on the landward side where the road enters the castle.",zh:"\u9646\u4FA7\u4E00\u5EA7\u77EE\u58EE\u7684\u57CE\u95E8\u697C\uFF0C\u9053\u8DEF\u7531\u6B64\u5165\u5821\u3002"},tour:{en:"The landward road reaches the castle here; this gatehouse is our invention.",zh:"\u9646\u8DEF\u5728\u6B64\u62B5\u8FBE\u57CE\u5821\uFF1B\u8FD9\u5EA7\u57CE\u95E8\u697C\u51FA\u81EA\u672C\u573A\u666F\u7684\u8BBE\u8BA1\u3002"},source:{confidence:"low",refs:["acok"],book:{en:"The castle has a gate, but its form is not described in what we recall.",zh:"\u57CE\u5821\u81EA\u6709\u57CE\u95E8\uFF0C\u4F46\u5C31\u6211\u4EEC\u6240\u8BB0\uFF0C\u4E66\u4E2D\u672A\u63CF\u5199\u5176\u5F62\u5236\u3002"},unknown:{en:"Number, position and design of the gates.",zh:"\u57CE\u95E8\u7684\u6570\u91CF\u3001\u4F4D\u7F6E\u4E0E\u8BBE\u8BA1\u3002"},interpretation:{en:"One landward gatehouse with a timber ramp; entirely invented.",zh:"\u9646\u4FA7\u4E00\u5EA7\u57CE\u95E8\u697C\uFF0C\u914D\u6728\u5761\u9053\uFF1B\u5B8C\u5168\u4E3A\u81EA\u62DF\u3002"}}},bailey:{name:{en:"Bailey",zh:"\u57CE\u5185\u9662\u843D"},desc:{en:"The yard inside the walls, with sheds and stables huddled in the lee of the tower.",zh:"\u57CE\u5899\u5185\u7684\u9662\u843D\uFF0C\u68DA\u5C4B\u4E0E\u9A6C\u53A9\u8737\u7F29\u5728\u5DE8\u5854\u7684\u80CC\u98CE\u5904\u3002"},tour:{en:"During Robert's Rebellion the garrison here starved for a year under siege.",zh:"\u52B3\u52C3\u8D77\u4E49\u671F\u95F4\uFF0C\u5B88\u519B\u5728\u6B64\u88AB\u56F4\u4E00\u5E74\uFF0C\u51E0\u8FD1\u997F\u6B7B\u3002"},source:{confidence:"low",refs:["agot","acok"],book:{en:"Stannis held the castle through a year-long siege until Davos smuggled in onions and salt fish. No yard buildings are described.",zh:"\u53F2\u5766\u5C3C\u65AF\u5728\u6B64\u575A\u5B88\u4E86\u4E00\u5E74\u7684\u56F4\u57CE\uFF0C\u76F4\u5230\u6234\u4F5B\u65AF\u5077\u8FD0\u8FDB\u6D0B\u8471\u4E0E\u54B8\u9C7C\u3002\u4E66\u4E2D\u672A\u63CF\u5199\u9662\u5185\u5EFA\u7B51\u3002"},unknown:{en:"All details of the yard.",zh:"\u9662\u843D\u7684\u4E00\u5207\u7EC6\u8282\u3002"},interpretation:{en:"A few slate-roofed halls and sheds; invented, since the tower itself holds the main rooms.",zh:"\u51E0\u5EA7\u677F\u5CA9\u9876\u5385\u5C4B\u4E0E\u68DA\u820D\uFF1B\u5747\u4E3A\u865A\u6784\uFF0C\u56E0\u4E3A\u4E3B\u8981\u5385\u5BA4\u90FD\u5728\u5DE8\u5854\u4E4B\u5185\u3002"}}},rookery:{name:{en:"Rookery",zh:"\u9E26\u5DE2"},desc:{en:"The maester's turret at the top of the drum tower, where ravens are kept.",zh:"\u9F13\u5854\u9876\u90E8\u7684\u5B66\u58EB\u5854\u697C\uFF0C\u6E21\u9E26\u517B\u5728\u8FD9\u91CC\u3002"},tour:{en:"From the top of the tower the maester's ravens fly out into the storms.",zh:"\u5B66\u58EB\u7684\u6E21\u9E26\u4ECE\u5854\u9876\u98DE\u51FA\uFF0C\u51B2\u8FDB\u98CE\u66B4\u3002"},source:{confidence:"medium",refs:["awoiaf"],book:{en:"Wiki summaries place the maester's chambers and rookery at the top of the tower.",zh:"\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u5B66\u58EB\u5C45\u6240\u4E0E\u9E26\u5DE2\u4F4D\u4E8E\u5854\u9876\u3002"},unknown:{en:"Which novel passage, if any, establishes this.",zh:"\u662F\u5426\u6709\u5C0F\u8BF4\u539F\u6587\u786E\u7ACB\u6B64\u70B9\uFF0C\u51FA\u81EA\u4F55\u5904\u3002"},interpretation:{en:"A small turret on the tower top with ravens circling.",zh:"\u5854\u9876\u4E00\u5EA7\u5C0F\u5854\u697C\uFF0C\u6E21\u9E26\u76D8\u65CB\u3002"}}},"seaward-cliff":{name:{en:"Seaward Cliff",zh:"\u4E34\u6D77\u60AC\u5D16"},desc:{en:"The sheer cliff the castle stands on; below it, rocks break the waves.",zh:"\u57CE\u5821\u6240\u7ACB\u7684\u9661\u5CED\u60AC\u5D16\uFF1B\u5D16\u4E0B\u7901\u77F3\u51FB\u788E\u6D6A\u5934\u3002"},tour:{en:"A sheer drop to the surf; no army comes from this side.",zh:"\u9661\u5D16\u76F4\u843D\u6D6A\u6D9B\u4E4B\u4E2D\uFF0C\u6CA1\u6709\u519B\u961F\u80FD\u4ECE\u8FD9\u4E00\u4FA7\u8FDB\u653B\u3002"},source:{confidence:"medium",refs:["acok","awoiaf"],book:{en:"The castle stands on a cliff above Shipbreaker Bay; wiki summaries give a drop of about 150 ft below the seaward wall.",zh:"\u57CE\u5821\u7ACB\u4E8E\u7834\u8239\u6E7E\u4E4B\u4E0A\u7684\u60AC\u5D16\uFF1B\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u4E34\u6D77\u57CE\u5899\u4E0B\u843D\u5DEE\u7EA6\u4E00\u767E\u4E94\u5341\u5C3A\u3002"},unknown:{en:"The exact height of the cliff.",zh:"\u60AC\u5D16\u7684\u786E\u5207\u9AD8\u5EA6\u3002"},interpretation:{en:"A smooth, steep cliff with sea stacks at its foot.",zh:"\u5E73\u6ED1\u9661\u5CED\u7684\u5D16\u58C1\uFF0C\u5D16\u811A\u7ACB\u7740\u6D77\u8680\u67F1\u3002"}}},"shipbreaker-bay":{name:{en:"Shipbreaker Bay",zh:"\u7834\u8239\u6E7E"},desc:{en:"The storm-lashed bay below the castle, named for the ships its waves and rocks have wrecked.",zh:"\u57CE\u5821\u4E0B\u65B9\u98CE\u66B4\u8086\u8650\u7684\u6D77\u6E7E\uFF0C\u56E0\u65E0\u6570\u8239\u53EA\u5728\u6B64\u89E6\u7901\u8986\u6CA1\u800C\u5F97\u540D\u3002"},tour:{en:"Shipbreaker Bay: grey water, hard weather and a name that explains itself.",zh:"\u7834\u8239\u6E7E\uFF1A\u7070\u8272\u6D77\u6C34\uFF0C\u6076\u52A3\u5929\u6C14\uFF0C\u540D\u5B57\u5DF2\u8BF4\u660E\u4E00\u5207\u3002"},source:{confidence:"high",refs:["agot","acok","maps"],book:{en:"Storm's End overlooks Shipbreaker Bay on the Stormlands coast.",zh:"\u98CE\u606F\u5821\u4FEF\u77B0\u98CE\u66B4\u5730\u6D77\u5CB8\u7684\u7834\u8239\u6E7E\u3002"},unknown:{en:"Depths, shoals and exact shape.",zh:"\u6C34\u6DF1\u3001\u6D45\u6EE9\u4E0E\u786E\u5207\u5F62\u72B6\u3002"},interpretation:{en:"A broad, rough sea with a few rocks and ships.",zh:"\u5F00\u9614\u800C\u6C79\u6D8C\u7684\u6D77\u9762\uFF0C\u70B9\u7F00\u51E0\u5757\u7901\u77F3\u4E0E\u51E0\u8258\u8239\u3002"}}},"kingswood-edge":{name:{en:"Kingswood Edge",zh:"\u5FA1\u6797\u8FB9\u7F18"},desc:{en:"The edge of the Kingswood to the north-west, dark oak crowns on the hills.",zh:"\u897F\u5317\u65B9\u7684\u5FA1\u6797\u8FB9\u7F18\uFF0C\u5C71\u5761\u4E0A\u4E00\u7247\u6DF1\u8272\u6A61\u6811\u51A0\u3002"},tour:{en:"North-west, the dark crowns of the Kingswood climb the hills.",zh:"\u897F\u5317\u65B9\uFF0C\u5FA1\u6797\u6DF1\u8272\u7684\u6811\u51A0\u6F2B\u4E0A\u5C71\u4E18\u3002"},source:{confidence:"medium",refs:["agot","maps"],book:{en:"The Kingswood is a great forest of the Stormlands lying north of Storm's End, between it and King's Landing.",zh:"\u5FA1\u6797\u662F\u98CE\u66B4\u5730\u7684\u5927\u68EE\u6797\uFF0C\u4F4D\u4E8E\u98CE\u606F\u5821\u4EE5\u5317\u3001\u98CE\u606F\u5821\u4E0E\u541B\u4E34\u4E4B\u95F4\u3002"},unknown:{en:"How close it comes to the castle.",zh:"\u68EE\u6797\u8DDD\u57CE\u5821\u6709\u591A\u8FD1\u3002"},interpretation:{en:"Only a hint of forest at the scene's edge; no distance is implied.",zh:"\u4EC5\u5728\u573A\u666F\u8FB9\u7F18\u7565\u4F5C\u6697\u793A\uFF1B\u4E0D\u4EE3\u8868\u5B9E\u9645\u8DDD\u79BB\u3002"}}},"fishing-hamlet":{name:{en:"Fishing Hamlet",zh:"\u6E14\u6751"},desc:{en:"A scatter of thatched cottages and boats on a low stretch of coast south of the headland.",zh:"\u5CAC\u89D2\u4EE5\u5357\u7684\u4F4E\u7F13\u6D77\u5CB8\u4E0A\uFF0C\u6563\u843D\u7740\u8305\u5C4B\u4E0E\u6E14\u8239\u3002"},tour:{en:"Fishermen shelter in the lee of the headland, boats hauled above the tide.",zh:"\u6E14\u6C11\u6816\u8EAB\u4E8E\u5CAC\u89D2\u80CC\u98CE\u5904\uFF0C\u6E14\u8239\u62D6\u5230\u6F6E\u7EBF\u4E4B\u4E0A\u3002"},source:{confidence:"low",refs:["acok"],book:{en:"Nothing specific; the books describe no village here.",zh:"\u65E0\u5177\u4F53\u8BB0\u8F7D\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u6B64\u5904\u6709\u6751\u843D\u3002"},unknown:{en:"Everything: name, location, size.",zh:"\u4E00\u5207\uFF1A\u540D\u79F0\u3001\u4F4D\u7F6E\u4E0E\u89C4\u6A21\u3002"},interpretation:{en:"A tiny invented hamlet, added for scale and life.",zh:"\u4E3A\u4F53\u73B0\u5C3A\u5EA6\u4E0E\u751F\u6C14\u800C\u865A\u6784\u7684\u5C0F\u6751\u843D\u3002"}}}}};export{e as default};
